"""Penjelasan tambahan halaman kalkulator · Regresi bagian 2 (robust sampai Tobit, 16 metode)."""
from .metode_extra import X

_ROB_DATA = ["Kolom Y dan satu atau lebih kolom X numerik.",
             "Jangan menghapus outlier lebih dulu; biarkan metode robust yang menentukan bobotnya.",
             "Periksa kembali pengamatan yang mendapat bobot kecil: salah catat, satuan berbeda, atau kasus khusus?"]

X("regresi-robust-m-estimator-huber",
  "Data harga rumah memuat beberapa transaksi yang jauh di atas pasaran, misalnya karena penjual tergesa-gesa atau salah ketik satu nol. Dengan OLS, beberapa titik itu menarik garis regresi dan mengubah kesimpulan. Penaksir Huber memberi bobot penuh pada pengamatan biasa dan menurunkan bobot pengamatan yang residualnya besar, sehingga garis lebih mewakili mayoritas data.",
  _ROB_DATA,
  [("Koefisien", "Ditafsirkan seperti regresi linear, tetapi kurang dipengaruhi outlier pada arah Y."),
   ("Perbandingan dengan OLS", "Selisih besar antara koefisien Huber dan OLS menandakan ada pengamatan yang berpengaruh kuat."),
   ("Diagnostik outlier", "Residual terskala dan bobot akhir setiap pengamatan. Bobot 1 berarti diperlakukan seperti OLS; bobot kecil berarti pengaruhnya diturunkan."),
   ("Grafik", "Garis Huber dan garis OLS pada satu diagram; titik berbobot kecil ditandai.")],
  ["Mengira Huber melindungi dari titik leverage tinggi (nilai X ekstrem); untuk itu gunakan LTS atau MM.",
   "Menghapus semua pengamatan berbobot kecil lalu menjalankan OLS lagi.",
   "Tidak melaporkan bahwa penaksiran robust dipakai dan alasannya."],
  "Contoh kalimat: “Karena terdapat beberapa transaksi ekstrem, digunakan regresi robust penaksir M Huber (c = 1,345). Luas bangunan berpengaruh nyata terhadap harga (b = 4,1 juta/m²; P < 0,001), lebih kecil daripada dugaan OLS (5,3 juta/m²) yang tertarik oleh tiga transaksi ekstrem.”",
  [("Apa arti konstanta 1,345?", "Batas residual terskala tempat bobot mulai diturunkan; nilai ini memberi efisiensi 95% bila galat sebenarnya normal."),
   ("Kapan Huber cukup, kapan perlu metode lain?", "Huber cukup untuk outlier pada Y. Bila ada nilai X ekstrem yang mencurigakan atau outlier sangat banyak, pakai LTS atau bisquare.")])

X("regresi-robust-tukey-bisquare",
  "Dalam data hasil laboratorium, beberapa sampel terkontaminasi sehingga nilainya jauh dari pola. Huber masih memberi sampel itu sedikit pengaruh. Bisquare Tukey menurunkan bobot secara halus dan memberi bobot nol pada residual yang sangat besar, sehingga pengamatan yang jelas menyimpang sama sekali tidak memengaruhi garis.",
  _ROB_DATA,
  [("Koefisien", "Ditafsirkan seperti regresi linear; sering hampir sama dengan OLS tanpa outlier."),
   ("Perbandingan dengan OLS", "Menunjukkan seberapa besar outlier menggeser dugaan OLS."),
   ("Diagnostik outlier", "Bobot nol menandai pengamatan yang praktis disisihkan; bobot di antara 0 dan 1 menunjukkan pengamatan yang dicurigai sebagian."),
   ("Grafik", "Garis bisquare dibanding OLS.")],
  ["Menjalankan bisquare dari nilai awal OLS saat outlier sangat besar; kalkulator memakai nilai awal robust untuk menghindarinya.",
   "Menganggap bobot nol sebagai bukti data salah; periksa dulu konteksnya.",
   "Memakai bisquare pada data kecil dengan banyak outlier tanpa membandingkan dengan metode lain."],
  "Contoh kalimat: “Regresi robust bisquare Tukey (c = 4,685) memberi bobot nol pada dua sampel yang terkontaminasi. Kemiringan kurva kalibrasi 0,982 (SE 0,011), sedangkan OLS memberikan 1,124.”",
  [("Apa bedanya dengan Huber?", "Huber tetap memberi outlier besar pengaruh terbatas; bisquare menghilangkan pengaruhnya sepenuhnya di atas batas c."),
   ("Apa itu penaksir MM?", "Penggabungan titik awal yang sangat robust (penaksir S) dengan langkah bisquare yang efisien; banyak dianggap pilihan terbaik untuk regresi robust.")])

X("regresi-robust-least-trimmed-squares-lts",
  "Data survei rumah tangga memuat sekelompok responden dari wilayah yang sangat berbeda, sehingga hampir sepertiga data mengikuti pola lain dan sebagian memiliki nilai X ekstrem. Metode M tidak cukup kuat menghadapinya. LTS mencari garis yang paling cocok untuk sekitar separuh data terbaik, sehingga tetap benar walaupun hampir separuh data menyimpang.",
  _ROB_DATA,
  [("Koefisien", "Dari himpunan pengamatan yang dipertahankan (biasanya setelah pembobotan ulang)."),
   ("Perbandingan dengan OLS", "Perbedaan besar menandakan OLS dikuasai oleh sekelompok pengamatan menyimpang."),
   ("Diagnostik outlier", "Pengamatan yang dipangkas dan residual terskalanya. Peta outlier membedakan outlier vertikal, titik leverage baik, dan titik leverage buruk."),
   ("Grafik", "Garis LTS dan OLS, dengan titik yang dipangkas ditandai.")],
  ["Melaporkan galat baku LTS mentah; efisiensinya rendah, sehingga biasanya diikuti langkah pembobotan ulang.",
   "Menganggap titik leverage baik sebagai pengganggu; titik itu mengikuti pola dan justru menambah ketelitian.",
   "Hasil dapat sedikit berubah antarjalankan karena algoritmanya memakai himpunan acak; laporkan bila itu terjadi."],
  "Contoh kalimat: “Untuk mengatasi sekelompok pengamatan menyimpang, digunakan regresi LTS (h = 0,5n) yang diikuti pembobotan ulang. Sebanyak 14 dari 120 rumah tangga teridentifikasi sebagai outlier; koefisien pendapatan berubah dari 0,12 (OLS) menjadi 0,31 (LTS terbobot ulang).”",
  [("Apa arti titik patah 50%?", "Hampir separuh data boleh salah sembarang tanpa membuat dugaan menjadi tak terbatas; OLS rusak hanya oleh satu titik."),
   ("Mengapa hasilnya bisa sedikit berbeda setiap dijalankan?", "Algoritma FAST-LTS memakai banyak subhimpunan acak; dengan data yang jelas, hasilnya praktis stabil.")])

X("regresi-kernel",
  "Hubungan antara suhu udara dan konsumsi listrik harian tidak berbentuk garis atau parabola: naik saat dingin (pemanas), turun di suhu sedang, lalu naik lagi saat panas (pendingin). Regresi kernel menaksir kurva langsung dari data dengan rata-rata berbobot di sekitar setiap titik, tanpa menentukan bentuk fungsi lebih dulu.",
  ["Kolom X dan Y numerik; sebaiknya cukup banyak pengamatan (puluhan atau lebih).",
   "Pilih kernel (Gauss, Epanechnikov, dan lainnya) dan derajat lokal (0 = Nadaraya–Watson, 1 = linear lokal).",
   "Biarkan bandwidth dipilih otomatis dengan validasi silang, atau isi sendiri dalam satuan X."],
  [("Perbandingan bandwidth", "Galat validasi silang untuk beberapa bandwidth; bandwidth kecil membuat kurva bergerigi, besar membuatnya terlalu halus."),
   ("Grafik", "Kurva dugaan di atas diagram pencar; perhatikan bagian tepi, tempat taksiran kurang pasti."),
   ("Nilai aktual dan prediksi", "Residual seharusnya tidak berpola terhadap X."),
   ("Interpretasi", "Ringkasan bentuk hubungan (naik, turun, titik balik) dalam kalimat.")],
  ["Memakai derajat 0 (Nadaraya–Watson) lalu terkejut melihat kurva melengkung di tepi; linear lokal mengurangi bias tepi.",
   "Memilih bandwidth sendiri supaya kurva “terlihat bagus”.",
   "Memakai kurva kernel untuk memprediksi di luar rentang data."],
  "Contoh kalimat: “Regresi kernel linear lokal (kernel Gauss, bandwidth 2,1 °C dipilih melalui validasi silang) menunjukkan konsumsi listrik minimum pada suhu sekitar 24 °C dan meningkat tajam di atas 30 °C.”",
  [("Apakah jenis kernel penting?", "Jauh kurang penting daripada bandwidth; kernel berbeda dengan bandwidth yang sesuai memberi kurva hampir sama."),
   ("Bagaimana bila ada banyak prediktor?", "Regresi kernel cepat kehilangan ketelitian di banyak dimensi; gunakan GAM yang aditif.")])

X("loess-lowess",
  "Peneliti ingin melihat tren kadar polutan selama 10 tahun tanpa terganggu fluktuasi harian dan beberapa nilai ekstrem akibat kebakaran. LOESS menyesuaikan garis lokal di sekitar setiap titik dengan bobot tricube, dan versi LOWESS menambahkan iterasi robust sehingga nilai ekstrem tidak menarik kurva.",
  ["Kolom X dan Y numerik.",
   "Span (proporsi data per jendela lokal) dapat dipilih otomatis dengan validasi silang.",
   "Centang iterasi robust (LOWESS) bila ada outlier."],
  [("Perbandingan span", "Galat validasi silang untuk beberapa span; span kecil lincah, span besar halus."),
   ("Grafik", "Kurva LOESS di atas diagram pencar, dengan pita kepercayaan bila tersedia."),
   ("Nilai aktual dan prediksi", "Residual untuk memeriksa pola yang belum tertangkap."),
   ("Interpretasi", "Ringkasan arah dan perubahan tren.")],
  ["Menganggap kurva LOESS sebagai model yang bisa ditulis dalam satu rumus.",
   "Memakai span sangat kecil sehingga derau ditafsirkan sebagai pola.",
   "Mengabaikan iterasi robust padahal ada nilai ekstrem."],
  "Contoh kalimat: “Kurva LOWESS (span 0,35; dua iterasi robust) menunjukkan kadar PM2,5 relatif stabil hingga 2019, lalu menurun sekitar 18% sampai 2023.”",
  [("Derajat 1 atau 2?", "Derajat 1 lebih stabil di tepi; derajat 2 lebih baik untuk kurva dengan puncak atau lembah tajam."),
   ("Apa beda LOESS dan LOWESS?", "LOWESS adalah versi asli Cleveland dengan iterasi robust; LOESS adalah perluasannya ke derajat 2 dan beberapa prediktor.")])

X("regresi-spline",
  "Pertumbuhan tinggi anak naik cepat di masa bayi, melambat di masa kanak-kanak, lalu melonjak lagi saat pubertas. Polinomial tunggal sulit mengikuti perubahan seperti ini. Spline menyambungkan potongan polinomial di beberapa titik simpul sehingga kurva lentur tetapi tetap mulus, dan tetap dapat dianalisis dengan alat regresi biasa.",
  ["Kolom X dan Y numerik.",
   "Pilih jenis spline (natural atau kubik); spline natural lebih stabil di tepi.",
   "Biarkan jumlah simpul dipilih otomatis, atau tentukan sendiri (3–5 simpul cukup untuk kebanyakan data)."],
  [("Pemilihan jumlah simpul", "AIC atau galat validasi silang untuk beberapa jumlah simpul; pilih yang terkecil atau yang paling sederhana dengan hasil hampir sama."),
   ("Posisi simpul", "Biasanya di kuantil X, sehingga setiap segmen berisi data yang cukup."),
   ("Grafik", "Kurva spline dengan pita kepercayaan; tafsirkan bentuk kurva, bukan koefisien basisnya."),
   ("Nilai aktual dan prediksi", "Residual untuk memeriksa kecocokan.")],
  ["Memakai terlalu banyak simpul sehingga kurva mengikuti derau.",
   "Menafsirkan koefisien basis spline satu per satu.",
   "Memakai spline kubik biasa yang liar di ujung, padahal spline natural lebih stabil."],
  "Contoh kalimat: “Hubungan umur dan tinggi badan dimodelkan dengan spline kubik natural empat simpul pada kuantil umur. Model spline lebih baik daripada model linear (uji F: P < 0,001) dan menunjukkan percepatan pertumbuhan pada umur 11–14 tahun.”",
  [("Spline atau polinomial?", "Spline biasanya lebih baik karena kelenturannya lokal: perubahan di satu bagian kurva tidak memengaruhi bagian lain."),
   ("Bagaimana menguji apakah hubungan linear?", "Bandingkan model spline dengan model linear menggunakan uji F atau AIC.")])

X("regresi-kuantil",
  "Peneliti pendidikan menduga bimbingan belajar lebih menolong siswa berprestasi rendah daripada siswa berprestasi tinggi. Regresi linear biasa hanya menjawab pengaruh terhadap rata-rata. Regresi kuantil menaksir pengaruh pada kuantil ke-10, median, kuantil ke-90, dan seterusnya, sehingga perbedaan pengaruh di seluruh sebaran nilai terlihat.",
  ["Kolom Y dan satu atau lebih kolom X numerik.",
   "Centang kuantil yang ingin ditaksir; 0,1; 0,25; 0,5; 0,75; dan 0,9 adalah pilihan umum.",
   "Ulangan bootstrap menentukan ketelitian galat baku; 100–200 biasanya cukup."],
  [("Koefisien per kuantil", "Perubahan kuantil Y per satuan X. Koefisien yang berbeda antarkuantil menunjukkan pengaruh X tidak seragam."),
   ("Galat baku bootstrap", "Dihitung dengan mengambil ulang pasangan data; tidak memerlukan asumsi normal."),
   ("Grafik koefisien", "Koefisien sebagai fungsi τ dibandingkan dengan koefisien OLS; garis yang miring menandakan pengaruh berbeda antarkuantil."),
   ("Nilai aktual dan prediksi (median)", "Kecocokan garis median dengan data.")],
  ["Menafsirkan koefisien kuantil ke-90 sebagai pengaruh pada “siswa terbaik”; itu adalah pengaruh pada kuantil bersyarat Y, bukan pada individu tertentu.",
   "Menaksir kuantil ekstrem (0,01 atau 0,99) dengan data sedikit.",
   "Tidak memeriksa garis kuantil yang saling bersilangan."],
  "Contoh kalimat: “Regresi kuantil menunjukkan pengaruh bimbingan belajar lebih besar pada kuantil bawah nilai ujian (τ = 0,1: b = 8,4; SE 1,9) dibanding kuantil atas (τ = 0,9: b = 2,1; SE 1,5), sedangkan OLS hanya memberi satu pengaruh rata-rata 5,0.”",
  [("Apa kelebihan regresi kuantil?", "Tahan terhadap outlier pada Y, tidak memerlukan ragam homogen, dan menunjukkan pengaruh di seluruh sebaran, bukan hanya rata-rata."),
   ("Mengapa galat baku memakai bootstrap?", "Rumus asimtotik bergantung pada kepadatan galat di kuantil itu, yang sulit ditaksir; bootstrap menghindari masalah tersebut.")])

X("generalized-additive-model-gam",
  "Ahli ekologi memodelkan kelimpahan ikan berdasarkan suhu air, kedalaman, dan salinitas. Pengaruh suhu jelas melengkung (ada suhu optimum), kedalaman tampak linear, dan bentuk pengaruh salinitas belum diketahui. GAM membiarkan setiap prediktor punya kurva sendiri yang bentuknya ditentukan data, sambil tetap menjumlahkannya dalam satu model yang dapat ditafsirkan.",
  ["Kolom Y numerik.",
   "Pilih prediktor yang diberi efek mulus s(X) dan prediktor yang dibiarkan linear.",
   "Basis per smooth menentukan kelenturan maksimum; nilai bawaan biasanya cukup, naikkan bila edf mendekati batasnya."],
  [("Suku halus", "Derajat bebas efektif (edf) dan uji setiap kurva. edf sekitar 1 berarti pengaruh praktis linear; edf besar berarti kurva berlekuk."),
   ("Suku linear", "Koefisien prediktor linear, ditafsirkan seperti regresi biasa."),
   ("GAM vs regresi linear", "Perbandingan AIC, R², dan galat; menunjukkan apakah kelenturan tambahan sepadan."),
   ("Grafik pengaruh parsial", "Bentuk kurva setiap prediktor dengan pita kepercayaan; inilah cara utama menafsirkan GAM.")],
  ["Memberi efek mulus pada semua prediktor tanpa alasan, sehingga model terlalu lentur.",
   "Menafsirkan P-value suku halus sebagai pasti; nilainya hampiran.",
   "Mengabaikan concurvity, yaitu prediktor yang kurvanya saling menjelaskan."],
  "Contoh kalimat: “GAM menunjukkan pengaruh suhu yang nonlinear terhadap kelimpahan ikan (edf = 3,6; P < 0,001) dengan optimum sekitar 27 °C, sedangkan kedalaman berpengaruh linear negatif (b = −0,04 per meter; P = 0,01). Model menjelaskan 64% deviance.”",
  [("Apa arti edf?", "Ukuran kelenturan kurva. edf 1 berarti garis lurus; edf 4 kira-kira sefleksibel polinomial derajat 4."),
   ("Apakah GAM bisa untuk respon biner atau cacahan?", "Bisa, dengan sebaran dan fungsi penghubung yang sesuai, seperti GLM. Kalkulator ini menangani respon numerik kontinu.")])

X("regresi-data-panel",
  "Peneliti ekonomi mengamati 34 provinsi selama 10 tahun untuk melihat pengaruh belanja pendidikan terhadap indeks pembangunan manusia. Setiap provinsi punya ciri tetap yang tidak terukur, seperti budaya atau sejarah. Regresi data panel memanfaatkan pengamatan berulang untuk mengendalikan ciri-ciri tetap itu.",
  ["Format panjang: satu baris per unit per periode, dengan kolom entitas, kolom waktu, Y, dan X.",
   "Panel seimbang (semua unit di semua periode) paling mudah, tetapi panel tidak seimbang tetap dapat dianalisis.",
   "Variabel yang tidak berubah sepanjang waktu tidak dapat ditaksir dalam model efek tetap."],
  [("Uji pemilihan model", "Uji Chow (common effect lawan fixed effect), uji Breusch–Pagan LM (common lawan random), dan uji Hausman (fixed lawan random). Ketiganya menentukan model yang dilaporkan."),
   ("Common, fixed, dan random effect", "Koefisien dari ketiga model; perbedaan besar antara common dan fixed menandakan bias akibat ciri unit yang tidak terukur."),
   ("Perbandingan koefisien", "Ringkasan ketiga model berdampingan."),
   ("Efek individu (FE)", "Intersep khusus setiap unit; menunjukkan unit mana yang tingkat dasarnya tinggi atau rendah.")],
  ["Memakai common effect (pooled OLS) tanpa menguji efek unit.",
   "Memilih random effect padahal uji Hausman nyata.",
   "Tidak memakai galat baku yang dikluster per unit."],
  "Contoh kalimat: “Uji Chow (P < 0,001) dan uji Hausman (χ² = 14,2; P = 0,003) menunjukkan model fixed effect paling sesuai. Setiap kenaikan 1% belanja pendidikan per kapita berkaitan dengan kenaikan IPM sebesar 0,08 poin (P = 0,004).”",
  [("Apa beda fixed effect dan random effect?", "Fixed effect hanya memakai variasi di dalam unit dan aman bila ciri unit berkorelasi dengan X; random effect lebih efisien tetapi bias bila korelasi itu ada."),
   ("Mengapa variabel seperti luas wilayah hilang di model FE?", "Karena tidak berubah sepanjang waktu sehingga terserap ke dalam efek tetap setiap unit.")])

X("regresi-deret-waktu-arimax",
  "Perusahaan ingin mengukur pengaruh belanja iklan bulanan terhadap penjualan. Penjualan bulan ini juga dipengaruhi oleh penjualan bulan sebelumnya, sehingga galat regresi biasa saling berkorelasi dan uji t menjadi terlalu optimistis. ARIMAX menggabungkan regresi pada iklan dengan model ARIMA untuk galatnya.",
  ["Kolom waktu (untuk pengurutan), kolom Y, dan satu atau lebih kolom X eksogen.",
   "Data harus berurutan tanpa periode yang hilang.",
   "Tentukan orde AR (p), diferensiasi (d), dan MA (q); mulai dari model sederhana seperti (1, 0, 0)."],
  [("Koefisien", "Pengaruh X terhadap Y setelah struktur autokorelasi galat diperhitungkan, beserta koefisien AR dan MA."),
   ("Perbandingan dengan OLS", "Galat baku OLS biasanya terlalu kecil bila galat berautokorelasi positif; bandingkan keduanya."),
   ("Autokorelasi galat", "ACF residual dan uji Ljung–Box; residual model yang baik tidak berautokorelasi."),
   ("Grafik", "Data aktual dan nilai dugaan sepanjang waktu.")],
  ["Meregresikan dua deret yang sama-sama naik terus tanpa differencing (regresi lancung).",
   "Lupa bahwa peramalan memerlukan nilai X masa depan.",
   "Memilih orde ARIMA yang terlalu besar untuk deret yang pendek."],
  "Contoh kalimat: “Model regresi dengan galat AR(1) (φ = 0,62) menunjukkan setiap tambahan Rp10 juta belanja iklan meningkatkan penjualan sebesar Rp38 juta (SE 12 juta; P = 0,002). Residual tidak berautokorelasi (Ljung–Box Q(12) = 9,8; P = 0,63).”",
  [("Apa arti d = 1?", "Model dianalisis pada selisih antarperiode, yang diperlukan bila deret tidak stasioner (misalnya terus naik)."),
   ("Bagaimana memilih p dan q?", "Lihat pola ACF dan PACF residual OLS, lalu bandingkan beberapa model dengan AIC.")])

X("regresi-spasial-sar-lag",
  "Harga tanah di suatu kecamatan dipengaruhi oleh harga tanah di kecamatan sekitarnya: pembangunan di satu wilayah menaikkan harga di wilayah tetangga. Model lag spasial (SAR) memasukkan rata-rata respon tetangga sebagai prediktor, sehingga efek limpahan antarwilayah dapat diukur.",
  ["Kolom koordinat (bujur dan lintang), kolom Y, dan kolom X.",
   "Pilih matriks bobot spasial: k tetangga terdekat atau berbasis jarak.",
   "Setiap baris mewakili satu wilayah; pastikan koordinat tidak ada yang kembar."],
  [("Uji autokorelasi spasial", "Moran’s I pada residual OLS dan uji LM; menunjukkan apakah model spasial diperlukan dan jenis mana (lag atau galat)."),
   ("Koefisien SAR", "ρ mengukur kekuatan ketergantungan respon antartetangga. Koefisien β tidak dapat dibaca langsung sebagai efek marginal."),
   ("Efek langsung, tidak langsung, total", "Efek langsung: pengaruh X di suatu wilayah terhadap wilayah itu sendiri; tidak langsung: limpahan ke wilayah lain; total: jumlahnya."),
   ("Koefisien OLS (pembanding)", "Biasanya bias pada model SAR karena mengabaikan ketergantungan spasial.")],
  ["Menafsirkan β sebagai efek marginal.",
   "Memilih model lag tanpa melihat uji LM; bila hanya LM-error yang nyata, model galat spasial lebih tepat.",
   "Memakai matriks bobot yang tidak masuk akal untuk wilayah studi."],
  "Contoh kalimat: “Uji LM-lag robust nyata (P = 0,004), sehingga digunakan model SAR (ρ = 0,41; P < 0,001). Efek total jarak ke pusat kota adalah −2,3 juta/m² per km, terdiri atas efek langsung −1,5 dan limpahan −0,8.”",
  [("Mengapa β bukan efek marginal?", "Perubahan X merambat ke tetangga lewat ρ dan kembali lagi; efek sebenarnya dirangkum dalam efek langsung dan tak langsung."),
   ("Berapa k tetangga yang tepat?", "Umumnya 4–8. Coba beberapa nilai dan pastikan kesimpulan tidak berubah drastis.")])

X("regresi-spasial-sem-error",
  "Hasil padi per kabupaten dipengaruhi oleh pupuk dan irigasi, tetapi juga oleh faktor yang tidak diukur, seperti jenis tanah dan iklim mikro, yang berpola spasial. Akibatnya galat regresi kabupaten yang berdekatan saling berkorelasi. Model galat spasial (SEM) menangani korelasi itu sehingga galat baku dan uji menjadi benar.",
  ["Kolom koordinat (bujur dan lintang), kolom Y, dan kolom X.",
   "Pilih matriks bobot spasial: k tetangga terdekat atau berbasis jarak.",
   "Satu baris per wilayah."],
  [("Uji autokorelasi spasial", "Moran’s I residual OLS dan uji LM-error serta LM-lag; SEM dipilih bila LM-error (robust) nyata."),
   ("Koefisien SEM", "λ mengukur korelasi spasial galat. Koefisien β ditafsirkan sebagai efek marginal seperti OLS."),
   ("Koefisien OLS (pembanding)", "Biasanya mirip dengan SEM, tetapi galat bakunya terlalu kecil.")],
  ["Menganggap korelasi spasial galat tidak masalah karena koefisien OLS tetap tak bias; galat baku dan uji menjadi salah.",
   "Memilih SEM padahal LM-lag robust yang nyata.",
   "Menyimpulkan tidak ada pola spasial dari Moran’s I pada data dengan sedikit wilayah; uji kurang kuat."],
  "Contoh kalimat: “Residual OLS menunjukkan autokorelasi spasial (Moran’s I = 0,32; P < 0,001), dan hanya uji LM-error robust yang nyata. Model galat spasial (λ = 0,48) menunjukkan pupuk N berpengaruh nyata terhadap hasil (b = 0,012 t/kg; SE 0,004).”",
  [("Kapan SEM, kapan SAR?", "SEM bila ketergantungan berasal dari faktor tak terukur yang berpola spasial; SAR bila respon wilayah benar-benar memengaruhi tetangganya. Uji LM membantu memilih."),
   ("Bagaimana bila kedua uji LM nyata?", "Pertimbangkan model Durbin spasial (SDM) atau model yang memuat keduanya.")])

X("geographically-weighted-regression-gwr",
  "Pengaruh pendidikan terhadap pendapatan mungkin kuat di kota besar tetapi lemah di daerah pedesaan. Regresi global hanya memberi satu angka rata-rata untuk seluruh wilayah. GWR menaksir regresi lokal di setiap lokasi dengan bobot yang menurun menurut jarak, sehingga menghasilkan peta koefisien yang menunjukkan di mana pengaruh itu kuat atau lemah.",
  ["Kolom koordinat (bujur dan lintang), kolom Y, dan kolom X.",
   "Sebaiknya ada cukup banyak lokasi (puluhan sampai ratusan).",
   "Biarkan bandwidth dipilih otomatis melalui validasi silang, atau tentukan jumlah tetangga terdekat."],
  [("Ringkasan koefisien lokal", "Minimum, kuartil, median, dan maksimum setiap koefisien di semua lokasi; rentang yang lebar menandakan hubungan beragam antarwilayah."),
   ("GWR vs OLS", "AICc dan R² kedua model; GWR yang AICc-nya jauh lebih kecil menandakan keragaman spasial nyata."),
   ("Koefisien tiap lokasi", "Nilai koefisien lokal untuk dipetakan."),
   ("Grafik", "Peta atau diagram koefisien lokal.")],
  ["Menafsirkan setiap pola peta sebagai nyata tanpa menguji keragaman koefisien.",
   "Memakai ratusan uji lokal tanpa koreksi uji berganda.",
   "Memakai bandwidth sangat kecil sehingga regresi lokal hanya berisi segelintir titik."],
  "Contoh kalimat: “GWR (bandwidth adaptif 42 tetangga) lebih baik daripada OLS (AICc 812 dibanding 851). Koefisien lama sekolah bervariasi dari 0,6 hingga 2,3 juta rupiah per tahun, tertinggi di wilayah perkotaan.”",
  [("Kapan GWR tepat dipakai?", "Bila ada alasan kuat bahwa hubungan berbeda antarwilayah dan tujuannya eksplorasi pola spasial."),
   ("Apa itu bandwidth adaptif?", "Jumlah tetangga terdekat yang tetap, sehingga jendela melebar di daerah yang jarang titiknya dan menyempit di daerah padat.")])

X("mixed-effect-model",
  "Nilai matematika 600 siswa dari 25 sekolah dihubungkan dengan jam belajar. Siswa dari sekolah yang sama cenderung mirip, sehingga pengamatan tidak saling bebas. Model efek campuran memberi setiap sekolah intersep acak (dan bila perlu kemiringan acak), sehingga galat baku benar dan keragaman antarsekolah dapat diukur.",
  ["Format panjang: satu baris per pengamatan, dengan kolom kelompok, Y, dan X.",
   "Kelompok sebaiknya cukup banyak (idealnya 10 atau lebih) agar ragam antarkelompok dapat ditaksir.",
   "Pilih kemiringan acak hanya untuk prediktor yang pengaruhnya memang diduga berbeda antarkelompok."],
  [("Efek tetap", "Koefisien rata-rata populasi, ditafsirkan seperti regresi biasa."),
   ("Komponen ragam dan ICC", "Ragam antarkelompok dan dalam kelompok; ICC adalah proporsi keragaman yang berasal dari kelompok."),
   ("Perbandingan dengan OLS", "Galat baku OLS biasanya terlalu kecil karena mengabaikan pengelompokan."),
   ("BLUP per kelompok", "Prediksi efek acak setiap kelompok, ditarik ke arah rata-rata umum; kelompok kecil ditarik lebih kuat.")],
  ["Mengabaikan pengelompokan dan memakai regresi biasa.",
   "Memasukkan kemiringan acak untuk banyak prediktor dengan kelompok sedikit, sehingga model gagal konvergen.",
   "Membandingkan model dengan efek tetap berbeda memakai REML."],
  "Contoh kalimat: “Model efek campuran dengan intersep acak sekolah menunjukkan setiap tambahan satu jam belajar per minggu meningkatkan nilai sebesar 1,8 poin (SE 0,3; P < 0,001). Sebanyak 22% keragaman nilai berasal dari perbedaan antarsekolah (ICC = 0,22).”",
  [("Efek tetap atau acak untuk sekolah?", "Acak bila sekolah dianggap contoh dari populasi sekolah dan tujuannya menggeneralisasi; tetap bila hanya tertarik pada sekolah-sekolah itu saja."),
   ("Mengapa BLUP berbeda dari rata-rata kelompok?", "Karena BLUP meminjam informasi dari semua kelompok: rata-rata kelompok kecil atau berderau ditarik ke rata-rata umum.")])

X("regresi-cox-survival",
  "Uji klinis membandingkan lama hidup pasien kanker dengan dua terapi, dengan memperhitungkan umur dan stadium. Sebagian pasien masih hidup ketika penelitian berakhir (tersensor). Regresi Cox memanfaatkan informasi dari pasien tersensor dan menghasilkan rasio hazard, tanpa perlu menentukan bentuk kurva hazard dasar.",
  ["Kolom waktu sampai kejadian atau sensor, dan kolom status (1 = kejadian, 0 = tersensor).",
   "Kovariat numerik dan kategorik.",
   "Pastikan satuan waktu konsisten, dan sensor tidak berkaitan dengan prognosis."],
  [("Koefisien dan hazard ratio", "HR = e^β. HR 0,6 berarti laju kejadian 40% lebih rendah pada setiap waktu; HR 1,5 berarti 50% lebih tinggi."),
   ("Uji proportional hazards", "Uji residual Schoenfeld; P kecil berarti rasio hazard berubah menurut waktu dan asumsi dilanggar untuk kovariat itu."),
   ("Hazard kumulatif dasar", "Untuk membentuk kurva survival dugaan bagi kombinasi kovariat tertentu."),
   ("Grafik", "Kurva survival per kelompok; kurva yang bersilangan menandakan masalah asumsi.")],
  ["Menghapus pasien tersensor atau menganggap mereka mengalami kejadian.",
   "Mengabaikan uji proportional hazards.",
   "Menafsirkan HR sebagai rasio peluang meninggal secara keseluruhan; HR adalah rasio laju sesaat."],
  "Contoh kalimat: “Setelah dikendalikan umur dan stadium, terapi B menurunkan hazard kematian sebesar 38% dibanding terapi A (HR = 0,62; IK 95%: 0,45–0,86; P = 0,004). Asumsi hazard proporsional terpenuhi (uji global P = 0,41).”",
  [("Mengapa hazard dasar tidak perlu ditentukan?", "Karena dalam kemungkinan parsial Cox, hazard dasar muncul di pembilang dan penyebut lalu saling meniadakan."),
   ("Bagaimana bila asumsi PH dilanggar?", "Stratifikasi menurut variabel itu, tambahkan interaksi dengan waktu, atau gunakan model waktu kegagalan dipercepat.")])

X("regresi-tobit",
  "Survei mengukur pengeluaran rumah tangga untuk rokok; banyak rumah tangga tidak mengeluarkan apa pun (nol), sisanya bervariasi. Regresi linear pada data ini bias karena tumpukan nol. Model Tobit mengandaikan ada kecenderungan laten yang hanya teramati bila positif, dan menaksir pengaruh pendapatan dengan memperhitungkan penyensoran itu.",
  ["Kolom Y dan kolom X numerik.",
   "Centang sensor kiri dan isi batas bawah (biasanya 0); sensor kanan dipakai bila ada batas atas, misalnya skor maksimum ujian.",
   "Unit dengan Y di batas harus tetap ada di data; Tobit bukan untuk data terpotong."],
  [("Koefisien Tobit", "Pengaruh X terhadap peubah laten; ini adalah batas atas pengaruh pada Y teramati."),
   ("Efek marjinal", "Pengaruh terhadap rata-rata Y teramati (β dikali peluang tidak tersensor); inilah angka yang paling relevan untuk kebijakan."),
   ("Perbandingan dengan OLS", "OLS biasanya meremehkan pengaruh karena tumpukan nol menekan kemiringan."),
   ("Sigma", "Simpangan baku galat laten; dipakai dalam perhitungan efek marjinal.")],
  ["Memakai OLS hanya pada pengamatan positif; tetap bias.",
   "Melaporkan koefisien laten seolah-olah efek terhadap pengeluaran teramati.",
   "Memakai Tobit padahal keputusan membeli dan jumlah pembelian dipengaruhi faktor berbeda; model dua bagian lebih tepat."],
  "Contoh kalimat: “Model Tobit (sensor kiri pada 0) menunjukkan pendapatan berpengaruh positif terhadap pengeluaran pendidikan (β = 0,084; P < 0,001). Efek marjinal pada rata-rata pengeluaran teramati adalah 0,052, artinya setiap tambahan Rp1 juta pendapatan menaikkan rata-rata pengeluaran pendidikan sebesar Rp52 ribu.”",
  [("Apa beda data tersensor dan terpotong?", "Tersensor: unit di batas tetap ada dalam data dengan nilai X-nya. Terpotong: unit di luar batas tidak masuk sampel sama sekali."),
   ("Kapan memakai model dua bagian (hurdle)?", "Bila keputusan ikut serta (nol atau positif) dan besaran bila positif ditentukan oleh faktor atau arah pengaruh yang berbeda.")])
